CREATE TABLE marketing_assets (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('form','content','domain','provider')),name TEXT NOT NULL,configuration_json TEXT NOT NULL,preview_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','rejected','retired')),created_by TEXT NOT NULL,reviewed_by TEXT,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE marketing_asset_events (id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES marketing_assets(id),version BIGINT NOT NULL,action TEXT NOT NULL,actor_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL,created_at BIGINT NOT NULL,UNIQUE(asset_id,version));
CREATE TABLE marketing_lead_candidates (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,branch_id TEXT NOT NULL,department_id TEXT,form_id TEXT NOT NULL REFERENCES marketing_assets(id),form_version BIGINT NOT NULL,contact_name TEXT NOT NULL,contact_detail TEXT NOT NULL,consent_evidence TEXT NOT NULL,attribution_json TEXT NOT NULL,brief TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','handed_off','rejected')),crm_lead_id TEXT REFERENCES crm_leads(id),created_by TEXT NOT NULL,reviewed_by TEXT,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE marketing_engagement_events (id TEXT PRIMARY KEY,candidate_id TEXT NOT NULL REFERENCES marketing_lead_candidates(id),version BIGINT NOT NULL,event_type TEXT NOT NULL,channel TEXT NOT NULL,evidence TEXT NOT NULL,actor_id TEXT NOT NULL,created_at BIGINT NOT NULL,UNIQUE(candidate_id,version));
CREATE FUNCTION marketing_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME IN ('marketing_asset_events','marketing_engagement_events') OR TG_OP='DELETE' THEN RAISE EXCEPTION 'MARKETING_HISTORY_IMMUTABLE' USING ERRCODE='23514'; END IF; IF TG_TABLE_NAME='marketing_assets' THEN IF (NEW.id,NEW.company_id,NEW.kind,NEW.configuration_json,NEW.preview_json,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.company_id,OLD.kind,OLD.configuration_json,OLD.preview_json,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'MARKETING_ASSET_SOURCE_IMMUTABLE' USING ERRCODE='23514'; END IF; ELSIF TG_TABLE_NAME='marketing_lead_candidates' THEN IF (NEW.id,NEW.company_id,NEW.branch_id,NEW.department_id,NEW.form_id,NEW.form_version,NEW.contact_name,NEW.contact_detail,NEW.consent_evidence,NEW.attribution_json,NEW.brief,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.company_id,OLD.branch_id,OLD.department_id,OLD.form_id,OLD.form_version,OLD.contact_name,OLD.contact_detail,OLD.consent_evidence,OLD.attribution_json,OLD.brief,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'MARKETING_CANDIDATE_SOURCE_IMMUTABLE' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['marketing_assets','marketing_asset_events','marketing_lead_candidates','marketing_engagement_events'] LOOP EXECUTE format('CREATE TRIGGER marketing_guard BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION marketing_guard()',t);END LOOP;END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['marketing_assets','marketing_lead_candidates'] LOOP INSERT INTO work_cache_revisions(table_name) VALUES(t) ON CONFLICT DO NOTHING;EXECUTE format('CREATE TRIGGER work_cache_change AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION work_cache_changed()',t);EXECUTE format('CREATE TRIGGER work_cache_truncate AFTER TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION work_cache_changed()',t);END LOOP;END $$;
